import React from 'react';
import styled, { CSSObject } from 'styled-components';

/**
 * @deprecated - Will be removed.
 */
export interface TextTruncationProps {
  /**
   * Limits the text to the given number of lines and adds ellipsis if the text would need more lines.
   * @deprecated - Will be removed.
   */
  maxLines?: number;
}

// #region StyledComponents
const StyledTruncateBox = /* @__PURE__ */ styled('span')<{ maxLines: number }>(
  ({ maxLines }) => {
    return maxLines > 1
      ? ({
          '@supports (display: -webkit-box)': {
            display: '-webkit-box',
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden',
            WebkitLineClamp: maxLines,
          },
        } as CSSObject)
      : ({
          display: 'block',
          whiteSpace: 'nowrap',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          maxWidth: '100%',
        } as CSSObject);
  },
);
// #endregion

/**
 * Hook to handle text truncation respecting the capsize concept for text by wrapping the given children
 * into a span that has the required styles applied.
 * See the [capsize FAQ](https://seek-oss.github.io/capsize/) for further info.
 * @deprecated - Will be removed.
 */
export function useTextTruncation(
  children: React.ReactNode,
  maxLines?: number,
): React.ReactNode {
  if (maxLines) {
    const maxLinesSanitized = Math.max(1, Math.round(maxLines));
    return (
      <StyledTruncateBox maxLines={maxLinesSanitized}>
        {children}
      </StyledTruncateBox>
    );
  }
  return children;
}
